   228  static void emit_lexeme(struct lexer *lexer, struct lexeme *lexeme)
   229  {
   230      if (!lexeme_buffer_emit(&lexer->buffer, lexeme))
   231          return;
   232
   233      lexer->start = lexer->pos;
   234  }
