   236  static void emit(struct lexer *lexer, enum lexeme_type type)
   237  {
   238      struct lexeme lexeme = {
   239          .type = type,
   240          .value = {
   241              .value = lexer->start,
   242              .len = (size_t)(lexer->pos - lexer->start)
   243          }
   244      };
   245      emit_lexeme(lexer, &lexeme);
   246  }
