   248  static int next(struct lexer *lexer)
   249  {
   250      if (lexer->pos >= lexer->end) {
   251          lexer->pos = lexer->end + 1;
   252          return '\0';
   253      }
   254
   255      int r = *lexer->pos;
   256      lexer->pos++;
   257
   258      if (r == '\n')
   259          lexer->cur_line++;
   260
   261      return r;
   262  }
