   264  static void ignore(struct lexer *lexer)
   265  {
   266      lexer->start = lexer->pos;
   267  }
   268
   269  static void advance_n(struct lexer *lexer, size_t n)
   270  {
   271      lexer->pos += n;
   272      ignore(lexer);
   273  }
