   275  static void backup(struct lexer *lexer)
   276  {
   277      lexer->pos--;
   278
   279      if (*lexer->pos == '\n')
   280          lexer->cur_line--;
   281  }
   282
   283  static int peek(struct lexer *lexer)
   284  {
   285      int chr = next(lexer);
   286
   287      backup(lexer);
   288
   289      return chr;
   290  }
