   295  static bool isstring(int chr)
   296  {
   297      return chr && !isspace(chr) && chr != '=' && chr != '#';
   298  }
   299
   300  static void *lex_string(struct lexer *lexer)
   301  {
   302      int chr;
   303
   304      do {
   305          chr = next(lexer);
   306
   307          if (chr == '$' && peek(lexer) == '{') {
   308              backup(lexer);
   309              emit(lexer, LEXEME_STRING);
   310
   311              advance_n(lexer, strlen("{"));
   312
   313              return lex_variable;
   314          }
   315      } while (isstring(chr));
   316
   317      backup(lexer);
   318      emit(lexer, LEXEME_STRING);
   319
   320      return lex_config;
   321  }
