   323  static void *lex_error(struct lexer *lexer, const char *msg)
   324  {
   325      struct lexeme lexeme = {
   326          .type = LEXEME_ERROR,
   327          .value = {
   328              .value = msg,
   329              .len = strlen(msg)
   330          }
   331      };
   332
   333      emit_lexeme(lexer, &lexeme);
   334
   335      return NULL;
   336  }
