   361  static void *lex_variable_default(struct lexer *lexer)
   362  {
   363      int chr;
   364
   365      do {
   366          chr = next(lexer);
   367
   368          if (chr == '}') {
   369              backup(lexer);
   370              emit(lexer, LEXEME_STRING);
   371
   372              advance_n(lexer, strlen("}"));
   373
   374              return lex_config;
   375          }
   376      } while (chr != '\0');
   377
   378      return lex_error(lexer, "EOF while scanning for end of variable");
   379  }
