   478  static bool lex_next(struct lexer *lexer, struct lexeme **lexeme)
   479  {
   480      while (lexer->state) {
   481          if (lexeme_buffer_consume(&lexer->buffer, lexeme))
   482              return true;
   483
   484          lexer->state = lexer->state(lexer);
   485      }
   486
   487      return lexeme_buffer_consume(&lexer->buffer, lexeme);
   488  }
