   504  static void *parse_key_value(struct parser *parser)
   505  {
   506      struct config_line line = {.type = CONFIG_LINE_TYPE_LINE};
   507      struct lexeme *lexeme;
   508      size_t key_size;
   509
   510      while (lexeme_buffer_consume(&parser->buffer, &lexeme)) {
   511          lwan_strbuf_append_str(&parser->strbuf, lexeme->value.value,
   512                                 lexeme->value.len);
   513
   514          if (!lexeme_ring_buffer_empty(&parser->buffer))
   515              lwan_strbuf_append_char(&parser->strbuf, '_');
   516      }
   517      key_size = lwan_strbuf_get_length(&parser->strbuf);
   518      lwan_strbuf_append_char(&parser->strbuf, '\0');
   519
   520      while (lex_next(&parser->lexer, &lexeme)) {
   520      while (lex_next(&parser->lexer, &lexeme)) {
   521          switch (lexeme->type) {
   522          case LEXEME_VARIABLE_DEFAULT:
   523          case LEXEME_VARIABLE: {
   524              const char *value;
   525
   526              value = secure_getenv_len(lexeme->value.value, lexeme->value.len);
   527              if (lexeme->type == LEXEME_VARIABLE) {
   528                  if (!value) {
   529                      lwan_status_error(
   530                          "Variable '$%.*s' not defined in environment",
   531                          (int)lexeme->value.len, lexeme->value.value);
   532                      return NULL;
   533                  } else {
   534                      lwan_strbuf_append_strz(&parser->strbuf, value);
   535                  }
   536              } else {
   537                  struct lexeme *var_name = lexeme;
   538
   539                  if (!lex_next(&parser->lexer, &lexeme)) {
   540                      lwan_status_error(
   541                          "Default value for variable '$%.*s' not given",
   542                          (int)var_name->value.len, var_name->value.value);
   543                      return NULL;
   544                  }
   545
   546                  if (lexeme->type != LEXEME_STRING) {
   547                      lwan_status_error("Wrong format for default value");
   548                      return NULL;
   549                  }
   550
   551                  if (!value) {
   552                      lwan_status_debug(
   553                          "Using default value of '%.*s' for variable '${%.*s}'",
   554                          (int)lexeme->value.len, lexeme->value.value,
   555                          (int)var_name->value.len, var_name->value.value);
   556                      lwan_strbuf_append_str(&parser->strbuf, lexeme->value.value,
   557                                             lexeme->value.len);
   558                  } else {
   559                      lwan_strbuf_append_strz(&parser->strbuf, value);
   560                  }
   561              }
   562
   563              break;
   564          }
   565
   566          case LEXEME_EQUAL:
   567              lwan_strbuf_append_char(&parser->strbuf, '=');
   568              break;
   569
   570          case LEXEME_STRING:
   571              lwan_strbuf_append_str(&parser->strbuf, lexeme->value.value,
   572                                     lexeme->value.len);
   573              break;
   574
   575          case LEXEME_CLOSE_BRACKET:
   576              backup(&parser->lexer);
   577              /* fallthrough */
   578
   579          case LEXEME_LINEFEED:
   580              line.key = lwan_strbuf_get_buffer(&parser->strbuf);
   581              line.value = line.key + key_size + 1;
   582              if (!config_buffer_emit(&parser->items, &line))
   583                  return NULL;
   584
   585              return parse_config;
   586
   587          default:
   588              lwan_status_error("Unexpected token while parsing key-value: %s",
   589                                lexeme_type_str[lexeme->type]);
   590              return NULL;
   591          }
   592      }
   593
   594      lwan_status_error("EOF while parsing key-value");
   595      return NULL;
   596  }
   597
   598  static void *parse_section(struct parser *parser)
   599  {
   600      struct lexeme *lexeme;
   601      size_t name_len;
   602
   603      if (!lexeme_buffer_consume(&parser->buffer, &lexeme))
   604          return NULL;
   605
   606      lwan_strbuf_append_str(&parser->strbuf, lexeme->value.value, lexeme->value.len);
   607      name_len = lexeme->value.len;
   608      lwan_strbuf_append_char(&parser->strbuf, '\0');
   609
   610      while (lexeme_buffer_consume(&parser->buffer, &lexeme)) {
   611          lwan_strbuf_append_str(&parser->strbuf, lexeme->value.value, lexeme->value.len);
   612
   613          if (!lexeme_ring_buffer_empty(&parser->buffer))
   614              lwan_strbuf_append_char(&parser->strbuf, ' ');
   615      }
   616
   617      struct config_line line = {
   618          .type = CONFIG_LINE_TYPE_SECTION,
   619          .key = lwan_strbuf_get_buffer(&parser->strbuf),
   620          .value = lwan_strbuf_get_buffer(&parser->strbuf) + name_len + 1
   621      };
   622      if (!config_buffer_emit(&parser->items, &line))
   623          return NULL;
   624
   625      return parse_config;
   626  }
   627
   628  static void *parse_section_shorthand(struct parser *parser)
   629  {
   630      void *next_state = parse_section(parser);
   631
   632      if (next_state) {
   633          struct config_line line = { .type = CONFIG_LINE_TYPE_SECTION_END };
   634
   635          if (!config_buffer_emit(&parser->items, &line))
   636              return NULL;
   637
   638          return next_state;
   639      }
   640
   641      return NULL;
   642  }
   643
   644  static void *parse_config(struct parser *parser)
   645  {
   646      struct lexeme *lexeme;
   647
   648      if (!lex_next(&parser->lexer, &lexeme))
   649          return NULL;
   650
   651      switch (lexeme->type) {
   652      case LEXEME_EQUAL:
   653          return parse_key_value;
   654
   655      case LEXEME_OPEN_BRACKET:
   656          return parse_section;
   657
   658      case LEXEME_LINEFEED:
   659          if (!lexeme_ring_buffer_empty(&parser->buffer))
   660              return parse_section_shorthand;
   661
   662          return parse_config;
   663
   664      case LEXEME_STRING:
   665          lexeme_buffer_emit(&parser->buffer, lexeme);
   666
   667          return parse_config;
   668
   669      case LEXEME_CLOSE_BRACKET: {
   670          struct config_line line = { .type = CONFIG_LINE_TYPE_SECTION_END };
   671
   672          config_buffer_emit(&parser->items, &line);
   673
   674          return parse_config;
   675      }
   676
   677      case LEXEME_EOF:
   678          return NULL;
   679
   680      default:
   681          lwan_status_error("Unexpected lexeme type: %s",
   682              lexeme_type_str[lexeme->type]);
   683          return NULL;
   684      }
   685  }
   686
   687  static bool parser_next(struct parser *parser, struct config_line **line)
   688  {
   689      while (parser->state) {
   690          if (config_buffer_consume(&parser->items, line))
   691              return true;
   692
   693          lwan_strbuf_reset(&parser->strbuf);
   694
   695          parser->state = parser->state(parser);
   696      }
   697
   698      return config_buffer_consume(&parser->items, line);
   699  }
