   737  static struct config *config_init_data(struct config *config,
   738                                         void *data, size_t len)
   739  {
   740      config->parser = (struct parser) {
   741          .state = parse_config,
   742          .lexer = {
   743              .state = lex_config,
   744              .pos = data,
   745              .start = data,
   746              .end = (char *)data + len,
   747              .cur_line = 1,
   748          }
   749      };
   750
   751      config->error_message = NULL;
   752
   753      lwan_strbuf_init(&config->parser.strbuf);
   754      config_ring_buffer_init(&config->parser.items);
   755      lexeme_ring_buffer_init(&config->parser.buffer);
   756
   757      return config;
   758  }
   759
   760  struct config *config_open(const char *path)
   761  {
   762      struct config *config;
   763      void *data;
   764      size_t len;
   765
   766      config = config_open_path(path, &data, &len);
   767      return config ? config_init_data(config, data, len) : NULL;
   768  }
