   770  #if defined(FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION)
   771  struct config *config_open_for_fuzzing(void *data, size_t len)
   772  {
   773      struct config *config = malloc(sizeof(*config));
   774
   775      if (config) {
   776          config->mapped.addr = NULL;
   777          config->mapped.sz = 0;
   778
   779          return config_init_data(config, data, len - 1);
