   786  void config_close(struct config *config)
   787  {
   788      if (!config)
   789          return;
   790
   791  #if !defined(FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION)
   792      if (config->mapped.addr)
   793          munmap(config->mapped.addr, config->mapped.sz);
   794  #endif
   795
   796      free(config->error_message);
   797      lwan_strbuf_free(&config->parser.strbuf);
   798      free(config);
   799  }
