   801  bool config_read_line(struct config *conf, struct config_line *cl)
   802  {
   803      struct config_line *ptr;
   804      bool ret;
   805
   806      if (conf->error_message)
   807          return false;
   808
   809      ret = parser_next(&conf->parser, &ptr);
   810      if (ret)
   811          *cl = *ptr;
   812
   813      return ret;
   814  }
