   816  static bool find_section_end(struct config *config)
   817  {
   818      struct config_line *line;
   819      int cur_level = 1;
   820
   821      if (config->error_message)
   822          return false;
   823
   824      while (parser_next(&config->parser, &line)) {
   825          if (line->type == CONFIG_LINE_TYPE_SECTION) {
   826              cur_level++;
   827          } else if (line->type == CONFIG_LINE_TYPE_SECTION_END) {
   828              cur_level--;
   829
   830              if (!cur_level)
   831                  return true;
   832          }
   833      }
   834
   835      return false;
   836  }
